import React from 'react';

export default function Blobs({ variant = 'default' }) {
  const sets = {
    default: [
      { w:600, h:600, top:'-20%', left:'-15%', bg:'radial-gradient(circle, rgba(80,60,180,0.22) 0%, transparent 70%)', anim:'float 12s ease-in-out infinite' },
      { w:400, h:400, top:'50%',  right:'-10%', bg:'radial-gradient(circle, rgba(40,40,120,0.18) 0%, transparent 70%)', anim:'floatB 9s ease-in-out infinite' },
      { w:300, h:300, bottom:'5%',left:'35%',  bg:'radial-gradient(circle, rgba(100,60,160,0.14) 0%, transparent 70%)', anim:'float 15s ease-in-out infinite 3s' },
    ],
    calm: [
      { w:700, h:700, top:'-25%', left:'-20%', bg:'radial-gradient(circle, rgba(40,60,160,0.2) 0%, transparent 70%)', anim:'float 14s ease-in-out infinite' },
      { w:350, h:350, bottom:'-5%',right:'-8%', bg:'radial-gradient(circle, rgba(60,40,140,0.16) 0%, transparent 70%)', anim:'floatB 10s ease-in-out infinite' },
    ],
    warm: [
      { w:500, h:500, top:'-10%', right:'-15%', bg:'radial-gradient(circle, rgba(120,60,100,0.2) 0%, transparent 70%)', anim:'floatB 11s ease-in-out infinite' },
      { w:400, h:400, bottom:'0', left:'-10%',  bg:'radial-gradient(circle, rgba(80,40,140,0.18) 0%, transparent 70%)', anim:'float 13s ease-in-out infinite' },
    ],
  };
  const blobs = sets[variant] || sets.default;
  return (
    <div style={{ position:'fixed', inset:0, zIndex:0, pointerEvents:'none', overflow:'hidden' }}>
      {blobs.map((b,i) => (
        <div key={i} style={{ position:'absolute', width:b.w, height:b.h, top:b.top, left:b.left, right:b.right, bottom:b.bottom, background:b.bg, filter:'blur(60px)', animation:b.anim }} />
      ))}
      {/* Film grain */}
      <div style={{ position:'absolute', inset:0, backgroundImage:`url("data:image/svg+xml,%3Csvg viewBox='0 0 200 200' xmlns='http://www.w3.org/2000/svg'%3E%3Cfilter id='n'%3E%3CfeTurbulence type='fractalNoise' baseFrequency='0.85' numOctaves='4' stitchTiles='stitch'/%3E%3C/filter%3E%3Crect width='100%25' height='100%25' filter='url(%23n)'/%3E%3C/svg%3E")`, opacity:0.03 }} />
    </div>
  );
}
